ALTER TABLE public.plan_versions ADD COLUMN includes_reservations_sales_tools boolean NOT NULL DEFAULT false;
ALTER TABLE public.custom_plans ADD COLUMN includes_reservations_sales_tools boolean NOT NULL DEFAULT false;
CREATE FUNCTION public.set_plan_tools(_id uuid,_custom boolean,_included boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admin only'; END IF; IF _custom THEN UPDATE custom_plans SET includes_reservations_sales_tools=_included WHERE id=_id; ELSE UPDATE plan_versions SET includes_reservations_sales_tools=_included WHERE id=_id; END IF; IF NOT FOUND THEN RAISE EXCEPTION 'Plan version not found'; END IF; END $$;
REVOKE ALL ON FUNCTION public.set_plan_tools(uuid,boolean,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.set_plan_tools(uuid,boolean,boolean) TO authenticated;
CREATE FUNCTION public.guard_plan_tools() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.includes_reservations_sales_tools IS DISTINCT FROM OLD.includes_reservations_sales_tools AND auth.uid() IS NOT NULL AND NOT has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Only admin can change reservations and sales tools inclusion'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_plan_tools BEFORE UPDATE ON public.plan_versions FOR EACH ROW EXECUTE FUNCTION public.guard_plan_tools(); CREATE TRIGGER guard_custom_tools BEFORE UPDATE ON public.custom_plans FOR EACH ROW EXECUTE FUNCTION public.guard_plan_tools();
CREATE FUNCTION public.who_pays(_version uuid DEFAULT NULL,_custom uuid DEFAULT NULL,_client uuid DEFAULT NULL,_launch uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE l client_launches; v uuid:=_version; cp uuid:=_custom; included boolean:=false; inf boolean:=false; nm text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF _client IS NOT NULL OR _launch IS NOT NULL THEN IF _launch IS NOT NULL THEN SELECT * INTO l FROM client_launches WHERE id=_launch; ELSE SELECT cl.* INTO l FROM client_launches cl JOIN clients c ON c.id=_client WHERE cl.client_id IN(c.id,c.parent_client_id) AND cl.status IN('active','live','on_hold','offboarding') ORDER BY (cl.client_id=c.id) DESC,cl.created_at DESC LIMIT 1; END IF; IF l.id IS NULL THEN RETURN NULL; END IF; IF NOT can_view_client(l.client_id) THEN RAISE EXCEPTION 'Client access required'; END IF; v:=l.plan_version_id; cp:=l.custom_plan_id; END IF; IF cp IS NOT NULL THEN SELECT name,includes_reservations_sales_tools INTO nm,included FROM custom_plans WHERE id=cp; SELECT EXISTS(SELECT 1 FROM custom_plan_services WHERE custom_plan_id=cp AND included AND pipeline_code='influencer') INTO inf; ELSE SELECT name,includes_reservations_sales_tools INTO nm,included FROM plan_versions WHERE id=v; SELECT EXISTS(SELECT 1 FROM plan_services WHERE plan_version_id=v AND included AND pipeline_code='influencer') INTO inf; END IF; IF nm IS NULL THEN RETURN NULL; END IF; RETURN jsonb_build_object('name',nm,'tools_included',included,'influencer_included',inf,'version',v,'custom',cp); END $$;
REVOKE ALL ON FUNCTION public.who_pays(uuid,uuid,uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.who_pays(uuid,uuid,uuid,uuid) TO authenticated;
CREATE TABLE public.influencer_programs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),launch_id uuid NOT NULL UNIQUE REFERENCES public.client_launches(id),client_id uuid NOT NULL REFERENCES public.clients(id),head_id uuid,contract_url text,status text NOT NULL DEFAULT 'needs_contract' CHECK(status IN('needs_contract','pending','changes_requested','approved')),owner_comment text,approved_by uuid,approved_at timestamptz,goals jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.influencer_programs TO authenticated; GRANT ALL ON public.influencer_programs TO service_role; ALTER TABLE public.influencer_programs ENABLE ROW LEVEL SECURITY; CREATE POLICY influencer_read ON public.influencer_programs FOR SELECT TO authenticated USING(public.can_view_client(client_id));
CREATE FUNCTION public.ensure_influencer_program(_launch uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l client_launches; h uuid; eligible boolean; BEGIN SELECT * INTO l FROM client_launches WHERE id=_launch; IF l.status NOT IN('draft','awaiting_day0','active','live') THEN RETURN; END IF; IF l.custom_plan_id IS NULL THEN SELECT EXISTS(SELECT 1 FROM plan_services WHERE plan_version_id=l.plan_version_id AND included AND pipeline_code='influencer') INTO eligible; ELSE SELECT EXISTS(SELECT 1 FROM custom_plan_services WHERE custom_plan_id=l.custom_plan_id AND included AND pipeline_code='influencer') INTO eligible; END IF; IF NOT eligible THEN RETURN; END IF; SELECT pm.user_id INTO h FROM pipeline_members pm JOIN pipelines p ON p.id=pm.pipeline_id WHERE p.code='influencer' AND pm.active AND pm.role='head' ORDER BY pm.created_at LIMIT 1; INSERT INTO influencer_programs(launch_id,client_id,head_id) VALUES(l.id,l.client_id,h) ON CONFLICT(launch_id) DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.ensure_influencer_program(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.ensure_influencer_program(uuid) TO service_role;
CREATE FUNCTION public.influencer_launch_touch() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM ensure_influencer_program(NEW.id); RETURN NEW; END $$; CREATE TRIGGER z_influencer_launch_touch AFTER INSERT OR UPDATE OF status,plan_version_id,custom_plan_id ON public.client_launches FOR EACH ROW EXECUTE FUNCTION public.influencer_launch_touch();
CREATE FUNCTION public.influencer_workspace(_client uuid DEFAULT NULL,_mine boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; RETURN (SELECT coalesce(jsonb_agg(jsonb_build_object('id',ip.id,'client_id',ip.client_id,'hotel',c.hotel_name,'status',ip.status,'contract_url',ip.contract_url,'comment',ip.owner_comment,'head',pr.full_name,'goals',ip.goals,'can_edit',is_pipeline_head(auth.uid(),p.id) AND can_view_client(ip.client_id),'can_approve',has_role(auth.uid(),'client') AND my_client_id() IN(ip.client_id,c.parent_client_id)) ORDER BY ip.created_at),'[]') FROM influencer_programs ip JOIN clients c ON c.id=ip.client_id JOIN client_launches l ON l.id=ip.launch_id LEFT JOIN profiles pr ON pr.id=ip.head_id JOIN pipelines p ON p.code='influencer' WHERE can_view_client(ip.client_id) AND (_client IS NULL OR ip.client_id=_client OR c.parent_client_id=_client) AND (NOT _mine OR is_pipeline_head(auth.uid(),p.id)) AND l.status IN('draft','awaiting_day0','active','live','on_hold','offboarding') AND (NOT _mine OR NOT c.is_test)); END $$;
REVOKE ALL ON FUNCTION public.influencer_workspace(uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.influencer_workspace(uuid,boolean) TO authenticated;
CREATE FUNCTION public.save_influencer_program(_id uuid,_contract text DEFAULT NULL,_goals jsonb DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ip influencer_programs; g jsonb; months int[]; BEGIN SELECT * INTO ip FROM influencer_programs WHERE id=_id FOR UPDATE; IF ip.id IS NULL OR NOT can_view_client(ip.client_id) OR NOT EXISTS(SELECT 1 FROM pipelines p WHERE p.code='influencer' AND is_pipeline_head(auth.uid(),p.id)) THEN RAISE EXCEPTION 'Assigned Influencer Program Head only'; END IF; IF client_on_hold(ip.client_id) THEN RAISE EXCEPTION 'This client is on hold'; END IF; IF _goals IS NOT NULL THEN IF ip.status<>'approved' THEN RAISE EXCEPTION 'Owner must approve the contract before goals are set'; END IF; IF jsonb_typeof(_goals)<>'array' OR jsonb_array_length(_goals)<>3 THEN RAISE EXCEPTION 'Enter goals for 3, 6 and 12 months'; END IF; FOR g IN SELECT value FROM jsonb_array_elements(_goals) LOOP IF (g->>'months')::int NOT IN(3,6,12) OR coalesce(trim(g->>'influencers'),'')='' OR coalesce((g->>'visits')::int,0)<1 THEN RAISE EXCEPTION 'Each goal needs influencers and at least one visit'; END IF; END LOOP; SELECT array_agg((value->>'months')::int ORDER BY (value->>'months')::int) INTO months FROM jsonb_array_elements(_goals); IF months<>ARRAY[3,6,12] THEN RAISE EXCEPTION 'Enter one goal each for 3, 6 and 12 months'; END IF; UPDATE influencer_programs SET goals=_goals,updated_at=now() WHERE id=_id; ELSE IF coalesce(trim(_contract),'') !~ '^https://' THEN RAISE EXCEPTION 'Add a secure contract link or uploaded file'; END IF; UPDATE influencer_programs SET contract_url=trim(_contract),status='pending',approved_by=NULL,approved_at=NULL,goals='[]',updated_at=now() WHERE id=_id; END IF; END $$;
REVOKE ALL ON FUNCTION public.save_influencer_program(uuid,text,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_influencer_program(uuid,text,jsonb) TO authenticated;
CREATE FUNCTION public.decide_influencer_program(_id uuid,_approve boolean,_comment text DEFAULT '') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ip influencer_programs; parent uuid; BEGIN SELECT * INTO ip FROM influencer_programs WHERE id=_id FOR UPDATE; SELECT parent_client_id INTO parent FROM clients WHERE id=ip.client_id; IF auth.uid() IS NULL OR NOT has_role(auth.uid(),'client') OR my_client_id() IS NULL OR NOT(my_client_id()=ip.client_id OR my_client_id()=parent) THEN RAISE EXCEPTION 'Only this hotel owner can approve'; END IF; IF ip.status<>'pending' THEN RAISE EXCEPTION 'Contract is not awaiting approval'; END IF; IF NOT _approve AND coalesce(trim(_comment),'')='' THEN RAISE EXCEPTION 'Add a comment when requesting changes'; END IF; UPDATE influencer_programs SET status=CASE WHEN _approve THEN 'approved' ELSE 'changes_requested' END,owner_comment=_comment,approved_by=CASE WHEN _approve THEN auth.uid() END,approved_at=CASE WHEN _approve THEN now() END,updated_at=now() WHERE id=_id; END $$;
REVOKE ALL ON FUNCTION public.decide_influencer_program(uuid,boolean,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.decide_influencer_program(uuid,boolean,text) TO authenticated;